-- Test data for the account smiechufabryka@gmail.com: a plan from 2026-09-21 (two weeks behind, the rest ahead), the
-- answers from onboarding, finished sessions with sets and weights, technique analyses, live-set summaries and a step
-- goal from the trainer. Technique analyses and live sets are marked as simulated, so the app shows „Dane przykładowe”.
-- Generated with the app's own Codable types, so the shapes are the ones CloudSync writes.
--
-- Run it in the Supabase SQL editor (or `supabase db execute`) of the Forma project, as the postgres role. The account
-- must exist: sign in once with Google as smiechufabryka@gmail.com, then run this. Safe to run again: it replaces its own
-- rows (same ids) and leaves anything else the account has. No video, poses, chat, Apple Health or check-ins here: those
-- never leave the phone.

do $seed$
declare uid uuid;
begin
  select id into uid from auth.users where email = 'smiechufabryka@gmail.com';
  if uid is null then
    raise exception 'No auth user smiechufabryka@gmail.com: sign in with Google in the app once, then run this again';
  end if;

    on conflict (user_id) do update set onboarding = excluded.onboarding;
    on conflict (user_id) do update set plan = excluded.plan;

  on conflict (user_id, kind, record_id) do update set data = excluded.data, occurred_at = excluded.occurred_at;
end
$seed$;
